import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing downstream (mocking: inprocess, fake gateway).
const prices = { A: 10, B: 33.33, C: 100.5, D: 0.1, E: 10.9, F: 50 }
const pricing = { calls: [], async priceOf(sku) { this.calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => (await (await post({ items })).json()).total

test('POST /orders: 201, JSON, id, echoed items and total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.deepEqual(order, { id: order.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
  assert.match(order.id, /^\d+$/)
})

test('order ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty over lines', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 1 }, { sku: 'F', qty: 1 }]), 60)
})

test('discount: none at or below 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 9 }]), 90)
})

test('discount: 10% once the pre-discount total is strictly above 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalOf([{ sku: 'A', qty: 20 }]), 180)
  assert.equal(await totalOf([{ sku: 'F', qty: 100 }]), 4500)
})

test('discount: boundary just above 100 gets the discount', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 100.1 is discounted to 90.09 (floored 90),
  // so a customer pays less for an order worth slightly more than one at exactly 100 (total 100).
  assert.equal(await totalOf([{ sku: 'D', qty: 1001 }]), 90)
  assert.equal(await totalOf([{ sku: 'C', qty: 1 }]), 90)
})

test('total is floored, never rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor truncates cents; 99.99 becomes 99,
  // and the total is a whole-euro integer, so cents are lost on every order.
  assert.equal(await totalOf([{ sku: 'B', qty: 3 }]), 99)
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 10)
  // CHARACTERIZATION: current behaviour may be unintended — floor applied after the discount: 110.9*0.9 = 99.81 -> 99.
  assert.equal(await totalOf([{ sku: 'E', qty: 10 }, { sku: 'A', qty: 2 }]), 116) // 129 -> 116.1 -> 116
})

test('discount applies to the whole order, not per line', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }, { sku: 'F', qty: 1 }, { sku: 'A', qty: 1 }]), 99) // 110 -> 99
})

test('unknown sku and bad quantities are not validated', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unknown sku has undefined price, total is NaN, serialised as null.
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
  // CHARACTERIZATION: current behaviour may be unintended — negative quantity yields a negative total.
  assert.equal(await totalOf([{ sku: 'A', qty: -5 }]), -50)
})

test('pricing is asked once per line, in order', async () => {
  pricing.calls.length = 0
  await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'F', qty: 1 }, { sku: 'A', qty: 1 }] })
  assert.deepEqual(pricing.calls, ['A', 'F', 'A'])
})

test('POST /orders: 400 for missing, empty, non-array items and invalid JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, 'not json')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/{id}: returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/{id}: unknown id', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unrouted requests: 404 no route', async () => {
  for (const res of [await fetch(`${base}/nope`), await fetch(`${base}/orders`), await fetch(`${base}/orders/1`, { method: 'DELETE' }), await fetch(`${base}/orders/1/x`)]) {
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
